"""Synthetic-only safety checks; all generated bytes stay below owned work/.

Tests of quarantine, quarantine restore and purge, and of release_set (storage_cleanup).
"""
from __future__ import annotations

import hashlib
import os
import stat
import unittest
from unittest import mock
import uuid

# Imported first: test_storage_policy puts scripts/ on sys.path for the product imports below.
from test_storage_policy import (FIXTURES, NativeStorageFixture, create_file_everyone_may_read, fixture_directory,
                                 make_directory_link, private_child)
from private_workspace import PrivateWorkspaceError, ensure_private_directory, ensure_private_file, write_private_new
from storage_ops import StorageRefusal, plan_sha256
import storage_cleanup
from storage_cleanup import release_set


class NativeStorageTests(NativeStorageFixture, unittest.TestCase):
    @unittest.skipUnless(os.name == "nt", "only on windows: Windows rename preserves file DACL; POSIX uses private directory traversal")
    def test_windows_broad_quarantine_source_holds_without_acl_change(self):
        source = FIXTURES / ("ordinary-public-source-" + uuid.uuid4().hex)
        os.mkdir(source)  # Inherits the fixture folder's ordinary DACL; no ACL is changed.
        target = source / "public-fixture.txt"
        create_file_everyone_may_read(target, b"fictional public source")
        with self.assertRaises(PrivateWorkspaceError) as caught:
            ensure_private_file(target)
        self.assertEqual(caught.exception.code, "private-dacl-broad-or-unknown")
        inventory = self.service.assess_storage(roots=[source])
        with mock.patch.object(self.service, "_hashed", side_effect=AssertionError("No source bytes before the privacy hold")) as hashing:
            with self.assertRaisesRegex(StorageRefusal, "Owner-private"):
                self.service.plan_cleanup(inventory=inventory, selected=["r001/public-fixture.txt"],
                                          quarantine_destination=self.output / "quarantine", content_read_authorized=True,
                                          recovery_required=False)
            hashing.assert_not_called()
        with self.assertRaises(PrivateWorkspaceError):
            ensure_private_file(target)
        self.assertTrue(target.exists())
        self.assertEqual(list(self.output.iterdir()), [])

    @unittest.skipUnless(os.name == "nt", "only on windows: actual Windows DACL preservation regression")
    def test_private_windows_quarantine_and_restore_recheck_file_acl(self):
        inventory = self.inventory()
        plan = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                          quarantine_destination=self.output / "quarantine", content_read_authorized=True,
                                          recovery_required=False)
        receipt = self.service.quarantine(plan=plan, expected_plan_sha256=plan_sha256(plan))
        ensure_private_directory(self.output / "quarantine")
        ensure_private_file(self.output / receipt["records"][0]["quarantine_record"]["relative_path"])
        restore = self.service.plan_quarantine_restore(receipt=receipt)
        self.service.restore_quarantine(plan=restore, expected_plan_sha256=plan_sha256(restore))
        ensure_private_file(self.source / "readme.txt")
        self.assertTrue((self.source / "readme.txt").exists())

    def test_generated_recovery_and_evidence_are_not_host_cleanup_targets(self):
        retained = self.output / "retained"
        retained.mkdir()
        (retained / "fictional-backup.zip").write_bytes(b"fictional protected archive marker")
        inventory = self.service.assess_storage(roots=[retained])
        with self.assertRaisesRegex(StorageRefusal, "stay protected"):
            self.service.plan_cleanup(inventory=inventory, selected=["r001/fictional-backup.zip"],
                                      quarantine_destination=self.output / "quarantine", content_read_authorized=True,
                                      recovery_required=False)

    def test_unknown_link_or_special_entry_in_the_quarantine_folder_refuses(self):
        # Only a person's selections list left-out entries as "not included"; PatchCairn's own quarantine folder
        # must hold exactly the receipt's files (sitting-b review).
        inventory = self.inventory()
        cleanup = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"], quarantine_destination=self.output / "quarantine",
                                            content_read_authorized=True, recovery_required=False)
        receipt = self.service.quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        folder = self.output / "quarantine"
        planted = [("planted-link", lambda path: make_directory_link(path, self.source / "notes"))]
        if os.name == "posix":
            planted.append(("planted-pipe", os.mkfifo))
        for name, plant in planted:
            plant(folder / name)
            with self.subTest(name=name), self.assertRaisesRegex(StorageRefusal, "Unknown, missing or changed quarantine files"):
                self.service.plan_quarantine_restore(receipt=receipt)
            # Remove only the exact synthetic entry just created (never a link's target), never recursion.
            os.rmdir(folder / name) if os.name == "nt" else (folder / name).unlink()
        self.assertEqual(self.service.plan_quarantine_restore(receipt=receipt)["kind"], "quarantine_restore")
        self.assertTrue((self.source / "notes" / "draft.md").is_file())

    def test_quarantine_restore_and_distinct_purge_plan(self):
        if os.name == "posix":
            # A quarantined source keeps its own mode behind the private quarantine parents (moved, never re-permissioned).
            (self.source / "readme.txt").chmod(0o644)
        inventory = self.inventory()
        _, backup = self.backup(inventory)
        probe = self.probe(backup)
        cleanup = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                            quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_backup=backup, recovery_verification=probe)
        self.assertEqual(cleanup["cost"]["expected_free_space_gain_bytes"], 0)
        receipt = self.service.quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        self.assertFalse((self.source / "readme.txt").exists())
        if os.name == "posix":
            self.assertEqual(stat.S_IMODE((self.output / "quarantine" / "000001").stat().st_mode), 0o644)
        self.assertTrue(self.service.verify_outcome(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup), receipt=receipt)["verification_passed"])
        purge = self.service.plan_purge(receipt=receipt)
        self.assertTrue(purge["irreversible"])
        self.assertTrue(purge["requires_separate_owner_approval"])
        with self.assertRaises(StorageRefusal):
            self.service.purge_quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        restore = self.service.plan_quarantine_restore(receipt=receipt)
        restored = self.service.restore_quarantine(plan=restore, expected_plan_sha256=plan_sha256(restore))
        self.assertTrue(self.service.verify_outcome(plan=restore, expected_plan_sha256=plan_sha256(restore), receipt=restored)["verification_passed"])
        self.assertEqual((self.source / "readme.txt").read_bytes(), b"fictional document\n")

    def test_unknown_quarantine_file_blocks_purge(self):
        inventory = self.inventory()
        cleanup = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                            quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_required=False)
        receipt = self.service.quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        (self.output / "quarantine" / "unknown.txt").write_bytes(b"fictional unregistered")
        with self.assertRaisesRegex(StorageRefusal, "Unknown"):
            self.service.plan_purge(receipt=receipt)

    def test_purge_removes_only_reviewed_quarantine_bytes(self):
        inventory = self.inventory()
        cleanup = self.service.plan_cleanup(inventory=inventory, selected=["r001/readme.txt"],
                                            quarantine_destination=self.output / "quarantine", content_read_authorized=True, recovery_required=False)
        receipt = self.service.quarantine(plan=cleanup, expected_plan_sha256=plan_sha256(cleanup))
        purge = self.service.plan_purge(receipt=receipt)
        result = self.service.purge_quarantine(plan=purge, expected_plan_sha256=plan_sha256(purge))
        self.assertTrue(result["irreversible"])
        self.assertTrue(self.service.verify_outcome(plan=purge, expected_plan_sha256=plan_sha256(purge), receipt=result)["verification_passed"])
        self.assertEqual(len(result["removed"]), 1)
        self.assertTrue((self.source / "copy.txt").exists())
        self.assertTrue((self.source / "large.bin").exists())


class ReleaseSetTests(unittest.TestCase):
    """release_set, the one deletion path of kept backups and recovery files; fictional files below work/ only."""

    def setUp(self):
        self.base = fixture_directory()
        self.kept, self.control = self.base / "kept", self.base / "control"
        private_child(self.base, "kept")
        private_child(self.base, "control")
        self.calls = []

    def file(self, name, data, folder=None):
        path = (folder or self.kept) / name
        write_private_new(path, data)
        return str(path), hashlib.sha256(data).hexdigest()

    def attempt(self, delete, absent, kept):
        self.calls.append({"delete": delete, "absent": absent, "kept": kept,
                           "present": sorted(path for path in delete if os.path.exists(path))})

    def test_deletes_exactly_the_listed_files_after_recording_the_attempt(self):
        first, first_sha = self.file("backup.zip", b"fictional archive")
        second, second_sha = self.file("manifest.json", b"fictional manifest")
        other, _ = self.file("unlisted.txt", b"fictional file nobody listed")
        gone = str(self.kept / "already-gone.txt")
        result = release_set({first: first_sha, second: second_sha, gone: "c" * 64}, attempt=self.attempt)
        self.assertEqual(result, {"removed": sorted([first, second]), "absent": [gone], "kept": []})
        # The attempt record names the exact paths, and is written while every one of them still exists.
        self.assertEqual(self.calls, [{"delete": sorted([first, second]), "absent": [gone], "kept": [], "present": sorted([first, second])}])
        self.assertFalse(os.path.exists(first) or os.path.exists(second))
        self.assertTrue(os.path.exists(other) and self.kept.is_dir())

    def test_kept_when_still_listed_unhashed_changed_or_a_control_record(self):
        listed, listed_sha = self.file("shared.zip", b"fictional shared archive")
        unhashed, _ = self.file("reserved.zip", b"fictional reserved archive")
        changed, _ = self.file("changed.zip", b"fictional archive, changed after it was recorded")
        record, record_sha = self.file("intent.json", b"fictional control record", folder=self.control)
        targets = {listed: listed_sha, unhashed: None, changed: hashlib.sha256(b"recorded bytes").hexdigest(), record: record_sha}
        # Another remaining row lists the shared path (named here with other letter case: a doubt keeps the file).
        result = release_set(targets, keep=[listed.upper() if os.name == "nt" else listed], never=[str(self.control)], attempt=self.attempt)
        reasons = {row["path"]: row["reason"] for row in result["kept"]}
        self.assertEqual(result["removed"], [])
        self.assertEqual(reasons[listed], "still-listed")
        self.assertEqual(reasons[unhashed], "no-recorded-hash")
        self.assertEqual(reasons[record], "control-record")
        self.assertEqual(reasons[changed], "stale-content")
        self.assertNotIn(changed, result["absent"])
        self.assertEqual(self.calls[0]["delete"], [changed])
        self.assertTrue(all(os.path.exists(path) for path in targets))

    def test_a_link_or_a_folder_is_never_followed_or_deleted(self):
        target_folder = self.base / "elsewhere"
        private_child(self.base, "elsewhere")
        inside, inside_sha = self.file("inside.txt", b"fictional file behind a link", folder=target_folder)
        link = self.kept / "linked"
        make_directory_link(link, target_folder)
        through, folder = str(link / "inside.txt"), str(self.kept)
        result = release_set({str(link): inside_sha, folder: inside_sha, through: inside_sha}, attempt=self.attempt)
        self.assertEqual(result["removed"], [])
        self.assertEqual({row["path"]: row["reason"] for row in result["kept"]}.get(str(link)), "not-a-file")
        self.assertEqual({row["path"]: row["reason"] for row in result["kept"]}.get(folder), "not-a-file")
        self.assertIn(through, [row["path"] for row in result["kept"]])
        self.assertTrue(os.path.exists(inside) and self.kept.is_dir())
        os.rmdir(link) if os.name == "nt" else link.unlink()

    def test_inexact_targets_are_refused_before_anything_is_recorded(self):
        path, sha = self.file("backup.zip", b"fictional archive")
        for targets in ({"relative.zip": sha}, {path + os.sep: sha}, {path: "not-a-hash"}, [path]):
            with self.subTest(targets=targets), self.assertRaises(StorageRefusal):
                release_set(targets, attempt=self.attempt)
        self.assertEqual(self.calls, [])
        self.assertTrue(os.path.exists(path))

    def test_a_chosen_destination_folder_is_opened_as_a_backup_destination(self):
        path, sha = self.file("backup.zip", b"fictional archive on a chosen drive")
        opened = []

        def destination(root, *, non_private_destination):
            opened.append((root, non_private_destination))
            return storage_cleanup.ScopedRoot(root, quiet_workspace=True)
        with mock.patch("storage_cleanup.admit_destination", side_effect=destination):
            result = release_set({path: sha}, destinations=[str(self.kept)], attempt=self.attempt)
            self.assertEqual(opened, [(str(self.kept), True)])
            other, other_sha = self.file("other.zip", b"fictional archive elsewhere", folder=self.control)
            release_set({other: other_sha}, destinations=[str(self.kept)], attempt=self.attempt)
            self.assertEqual(len(opened), 1)
        self.assertEqual(result["removed"], [path])


if __name__ == "__main__":
    unittest.main(verbosity=2)
